const fetchAttempts = () => apiGet<Attempt[]>("/pte/attempts");
const fetchPlan = () => apiGet<StudyPlan>("/pte/study-plan");
const fetchPricing = () => apiGet<PricingPlan[]>("/pte/pricing");

function ScoreRing({ score, target }: { score: number; target: number }) {
  const progress = Math.max(0, Math.min(100, ((score - 10) / 80) * 100));
  return <div className="relative flex h-44 w-44 items-center justify-center" data-testid="pte-overall-score-gauge"><div className="absolute inset-1 rounded-full shadow-[0_18px_50px_rgba(2,132,199,0.18)]" style={{ background: `conic-gradient(from 220deg, #0d9488 0%, #0284c7 ${progress}%, #e2e8f0 ${progress}%)` }} /><div className="absolute inset-4 rounded-full bg-white" /><div className="relative text-center"><div className="font-mono text-5xl font-bold tracking-[-0.08em] text-slate-900" data-testid="overall-score-value">{score}</div><div className="mt-1 text-[10px] font-bold uppercase tracking-[0.2em] text-slate-400" data-testid="overall-score-label">estimated overall</div></div><div className="absolute -bottom-1 rounded-full border border-sky-100 bg-white px-2.5 py-1 text-[10px] font-bold uppercase tracking-wider text-sky-700 shadow-sm" data-testid="target-score-marker">Target {target}+</div></div>;
}

function SkillCard({ skill, score, task, onPractice }: { skill: Skill; score: number; task?: PteTask; onPractice: (task?: PteTask) => void }) {
  const meta = skillMeta[skill];
  const Icon = meta.icon;
  return <button type="button" onClick={() => onPractice(task)} className="group rounded-xl border border-slate-200 bg-white p-4 text-left shadow-sm transition-[transform,box-shadow,border-color] duration-200 hover:-translate-y-1 hover:border-slate-300 hover:shadow-lg" data-testid={`skill-card-${skill.toLowerCase()}`}><div className="flex items-start justify-between"><span className={`flex size-9 items-center justify-center rounded-lg ${meta.bg}`} style={{ color: meta.color }}><Icon size={18} /></span><span className="font-mono text-2xl font-bold text-slate-900" data-testid={`${skill.toLowerCase()}-score`}>{score}</span></div><div className="mt-5 flex items-end justify-between gap-2"><div><div className="text-sm font-bold text-slate-900" data-testid={`${skill.toLowerCase()}-skill-name`}>{skill}</div><div className="mt-1 text-xs text-slate-500">{meta.copy}</div></div><ChevronRight className="mb-1 text-slate-300 transition-transform duration-200 group-hover:translate-x-1" size={16} /></div><div className="mt-4 h-1.5 overflow-hidden rounded-full bg-slate-100"><div className="h-full rounded-full" style={{ width: `${(score / 90) * 100}%`, backgroundColor: meta.color }} /></div></button>;
}

function TaskCard({ task, onSelect }: { task: PteTask; onSelect: () => void }) {
  const meta = skillMeta[task.skill];
  const Icon = meta.icon;
  return <div className="group flex flex-col justify-between rounded-xl border border-slate-200 bg-white p-5 shadow-sm transition-[transform,box-shadow] duration-200 hover:-translate-y-0.5 hover:shadow-md" data-testid={`task-card-${task.id}`}><div><div className="flex items-start justify-between gap-3"><span className="flex size-9 items-center justify-center rounded-lg bg-slate-50" style={{ color: meta.color }}><Icon size={17} /></span><Badge variant="outline" data-testid={`${task.id}-difficulty`}>{task.difficulty}</Badge></div><div className="mt-5 text-base font-bold text-slate-900" data-testid={`${task.id}-title`}>{task.title}</div><div className="mt-1 text-xs font-medium text-slate-500">{task.skill} · {task.response_type === "audio" ? "Audio response" : "Text response"}</div></div><Button className="mt-5 w-full" size="sm" onClick={onSelect} data-testid={`${task.id}-practice-button`}><Play size={14} fill="currentColor" /> Practice now</Button></div>;
}

function FeedbackView({ attempt, onBack, onRetry }: { attempt: Attempt; onBack: () => void; onRetry: () => void }) {
  return <div className="mx-auto max-w-5xl animate-rise space-y-6"><div className="flex flex-wrap items-center justify-between gap-4"><div><div className="label-mono text-teal-700" data-testid="feedback-eyebrow">Practice review</div><h1 className="mt-2 text-3xl font-extrabold tracking-tight text-slate-950" data-testid="feedback-title">Your practice snapshot</h1><p className="mt-2 text-sm text-slate-500">A transparent estimate with a clear next step.</p></div><Badge className={`${attempt.ai_feedback ? "border-teal-100 bg-teal-50 text-teal-700" : "border-amber-100 bg-amber-50 text-amber-700"}`} variant="outline" data-testid="feedback-provider-badge"><Sparkles size={13} /> {attempt.ai_feedback ? "AI review complete" : "Fallback review complete"}</Badge></div><div className="grid gap-6 lg:grid-cols-[0.9fr_1.3fr]"><Card className="overflow-hidden border-0 bg-slate-950 text-white shadow-xl shadow-slate-900/10" data-testid="feedback-score-card"><CardContent className="relative p-7"><div className="absolute -right-12 -top-16 size-48 rounded-full bg-teal-400/20 blur-3xl" /><div className="relative"><div className="label-mono text-sky-300">Estimated practice score</div><div className="mt-7 font-mono text-7xl font-bold tracking-[-0.1em]" data-testid="feedback-score-value">{attempt.score}</div><div className="mt-2 text-sm text-slate-300" data-testid="feedback-task-name">{attempt.task_title} · {attempt.skill} · {attempt.difficulty}</div><div className="mt-8 h-px bg-white/10" /><div className="mt-5 flex items-center gap-2 text-xs text-slate-300" data-testid="feedback-disclaimer"><Info size={14} className="text-sky-300" /> Practice estimate, never an official Pearson score</div></div></CardContent></Card><Card className="border-slate-200 shadow-sm" data-testid="feedback-traits-card"><CardHeader className="border-b border-slate-100"><CardTitle className="text-lg" data-testid="feedback-traits-title">Skill breakdown</CardTitle></CardHeader><CardContent className="grid gap-5 p-6 sm:grid-cols-3">{attempt.traits.map((trait) => <div key={trait.label} data-testid={`feedback-trait-${trait.label.toLowerCase().replaceAll(" ", "-")}`}><div className="flex items-center justify-between text-sm"><span className="font-semibold text-slate-700">{trait.label}</span><span className="font-mono font-bold text-slate-950">{trait.score}</span></div><div className="mt-3 h-2 rounded-full bg-slate-100"><div className="h-full rounded-full" style={{ width: `${(trait.score / 90) * 100}%`, backgroundColor: trait.color }} /></div></div>)}</CardContent></Card></div><div className="grid gap-6 lg:grid-cols-[1.3fr_0.9fr]"><Card className="border-slate-200 shadow-sm" data-testid="feedback-notes-card"><CardHeader><CardTitle className="text-lg">Coach notes</CardTitle></CardHeader><CardContent className="space-y-3">{attempt.feedback.map((note, index) => <div className="flex gap-3 rounded-lg bg-slate-50 p-4 text-sm leading-relaxed text-slate-600" key={`${note}-${index}`} data-testid={`feedback-note-${index + 1}`}><span className="mt-0.5 flex size-5 shrink-0 items-center justify-center rounded-full bg-teal-100 text-teal-700"><Check size={13} /></span><span>{note}</span></div>)}</CardContent></Card><Card className="border-sky-100 bg-sky-50/60 shadow-sm" data-testid="next-step-card"><CardHeader><div className="flex size-9 items-center justify-center rounded-lg bg-white text-sky-600 shadow-sm"><Target size={18} /></div><CardTitle className="mt-3 text-lg">Keep the momentum</CardTitle></CardHeader><CardContent><p className="text-sm leading-relaxed text-slate-600">Your next best move is one more {attempt.skill.toLowerCase()} task while the strategy is fresh.</p><Button className="mt-5 w-full" onClick={onRetry} data-testid="feedback-practice-again-button">Practice again <ArrowRight size={15} /></Button></CardContent></Card></div><Button variant="outline" onClick={onBack} data-testid="feedback-back-dashboard-button"><LayoutDashboard size={15} /> Back to dashboard</Button></div>;
}

function PracticeListeningAudio({ script, audioUrl }: { script: string; audioUrl: string | null }) {
  const [showTranscript, setShowTranscript] = useState(false);
  const [playing, setPlaying] = useState(false);
  const play = () => {
    setPlaying(true);
    if (audioUrl) {
      const audio = new Audio(audioUrl);
      audio.onended = () => setPlaying(false);
      audio.onerror = () => { setPlaying(false); toast.error("Audio could not play. Please try again."); };
      void audio.play();
      return;
    }
    const utterance = new SpeechSynthesisUtterance(script);
    utterance.rate = 0.9;
    utterance.onend = () => setPlaying(false);
    utterance.onerror = () => setPlaying(false);
    window.speechSynthesis.cancel();
    window.speechSynthesis.speak(utterance);
  };
  return <div className="mt-5 rounded-xl border border-indigo-100 bg-indigo-50/70 p-4" data-testid="practice-listening-audio"><div className="flex flex-wrap items-center justify-between gap-3"><div><div className="text-sm font-bold text-slate-900" data-testid="practice-listening-audio-title">Listen before answering</div><div className="mt-1 text-xs text-slate-500">The transcript is hidden unless you choose to reveal it.</div></div><Button type="button" variant="outline" onClick={play} data-testid="practice-play-audio-button"><Volume2 size={15} /> {playing ? "Playing…" : "Play audio"}</Button></div><button type="button" className="mt-3 text-xs font-bold text-indigo-700 hover:underline" onClick={() => setShowTranscript((value) => !value)} data-testid="practice-toggle-transcript-button">{showTranscript ? "Hide transcript" : "Show transcript"}</button>{showTranscript && <div className="mt-3 rounded-lg bg-white p-3 text-sm leading-6 text-slate-700" data-testid="practice-listening-transcript">{script}</div>}</div>;
}

function PracticeCenter({ tasks, level, setLevel, selectedTask, setSelectedTask, answer, setAnswer, source, setSource, audioDuration, setAudioDuration, isSubmitting, onSubmit, onBack, onTaskTest = setSelectedTask }: { tasks: PteTask[]; level: Difficulty; setLevel: (level: Difficulty) => void; selectedTask: PteTask | null; setSelectedTask: (task: PteTask | null) => void; answer: string; setAnswer: (answer: string) => void; source: "text" | "audio"; setSource: (source: "text" | "audio") => void; audioDuration: number | undefined; setAudioDuration: (duration: number) => void; isSubmitting: boolean; onSubmit: () => void; onBack: () => void; onTaskTest?: (task: PteTask) => void }) {
  const groups = useMemo(() => tasks.reduce<Record<Skill, PteTask[]>>((result, task) => { result[task.skill].push(task); return result; }, { Speaking: [], Writing: [], Reading: [], Listening: [] }), [tasks]);
  if (!selectedTask) return <div className="mx-auto max-w-7xl animate-rise space-y-7"><div><div className="label-mono text-teal-700">Practice center</div><h1 className="mt-2 text-3xl font-extrabold tracking-tight text-slate-950" data-testid="practice-center-title">Choose a practice type</h1><p className="mt-2 text-sm text-slate-500">Every type opens a saved 10-question test library. Generate, import, or build a test before you start.</p></div>{skills.map((skill) => <section key={skill} data-testid={`practice-section-${skill.toLowerCase()}`}><div className="mb-3 flex items-center gap-2"><span className="size-2 rounded-full" style={{ backgroundColor: skillMeta[skill].color }} /><h2 className="text-lg font-bold text-slate-900">{skill}</h2><span className="text-xs text-slate-400">{groups[skill].length} practice types</span></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{groups[skill].map((task) => <TaskCard task={task} onSelect={() => onTaskTest(task)} key={task.id} />)}</div></section>)}</div>;
  if (selectedTask && Date.now() >= 0) return <TaskTestLibrary task={selectedTask} onBack={() => setSelectedTask(null)} />;
  const isSpeaking = selectedTask.skill === "Speaking";
  const isChoice = selectedTask.response_type === "choice";
  return <div className="mx-auto max-w-5xl animate-rise space-y-6"><div className="flex flex-wrap items-center justify-between gap-4"><div><button type="button" className="mb-4 flex items-center gap-1 text-xs font-bold text-slate-500 transition-colors hover:text-slate-900" onClick={() => setSelectedTask(null)} data-testid="practice-back-list-button"><ArrowLeft size={14} /> All tasks</button><div className="label-mono text-sky-700">{selectedTask.skill} · {selectedTask.task_type}</div><h1 className="mt-2 text-3xl font-extrabold tracking-tight text-slate-950" data-testid="practice-title">{selectedTask.title}</h1></div><div className="flex items-center gap-3"><LevelPicker level={level} setLevel={setLevel} testId="practice-selected-level" /><div className="flex items-center gap-2 rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs font-semibold text-slate-600" data-testid="practice-timer"><Clock3 size={15} className="text-sky-600" /> {selectedTask.duration_seconds}s suggested</div></div></div><div className="grid gap-6 lg:grid-cols-[1.05fr_0.95fr]"><Card className="border-slate-200 shadow-sm" data-testid="prompt-card"><CardHeader className="border-b border-slate-100"><div className="flex items-center justify-between"><div><div className="label-mono text-slate-400">Prompt</div><CardTitle className="mt-2 text-xl">Read the task carefully</CardTitle></div><Badge variant="outline" data-testid="prompt-difficulty">{selectedTask.difficulty}</Badge></div></CardHeader><CardContent className="p-6">{selectedTask.visual && <VisualChart visual={selectedTask.visual} />}<div className={`${selectedTask.visual ? "mt-5" : ""} rounded-xl bg-slate-50 p-5 text-base font-medium leading-8 text-slate-800`} data-testid="task-prompt">{selectedTask.prompt}</div><div className="mt-5 flex gap-3 rounded-lg border border-sky-100 bg-sky-50/60 p-4 text-sm leading-relaxed text-slate-600" data-testid="task-instructions"><Info size={16} className="mt-0.5 shrink-0 text-sky-600" /> {selectedTask.instructions}</div>{selectedTask.listening_script && <PracticeListeningAudio script={selectedTask.listening_script} audioUrl={selectedTask.audio_url} />}{isSpeaking && <div className="mt-5"><AudioRecorder onTranscript={(transcript, duration) => { setAnswer(transcript); setAudioDuration(duration); setSource("audio"); }} onPermissionChange={(granted) => { if (!granted) { setAnswer(""); setSource("text"); } }} onError={(message) => toast.error("Microphone required", { description: message })} /></div>}</CardContent></Card><Card className="border-slate-200 shadow-sm" data-testid="answer-card"><CardHeader><div className="label-mono text-slate-400">Your answer</div><CardTitle className="mt-2 text-xl">Show what you know</CardTitle></CardHeader><CardContent>{isSpeaking ? <div className="rounded-xl border border-teal-100 bg-teal-50/60 p-4 text-sm leading-relaxed text-teal-900" data-testid="speaking-microphone-required">Record your spoken answer on the left. Typed answers are disabled for speaking so feedback can use your recording and transcript.</div> : isChoice ? <div className="space-y-2" data-testid="choice-answer-list">{selectedTask.options.map((option) => <button type="button" key={option} onClick={() => setAnswer(option)} className={`flex w-full items-center justify-between rounded-lg border px-4 py-3 text-left text-sm font-semibold transition-[background-color,border-color,transform] ${answer === option ? "border-sky-500 bg-sky-50 text-sky-800" : "border-slate-200 bg-slate-50 text-slate-600 hover:border-slate-300 hover:bg-white"}`} data-testid={`choice-option-${option.toLowerCase().replaceAll(" ", "-")}`}>{option}{answer === option && <Check size={15} />}</button>)}</div> : <Textarea value={answer} onChange={(event) => setAnswer(event.target.value)} placeholder="Write your response here..." className="min-h-64 resize-y border-slate-200 bg-slate-50/60 p-4 leading-7 focus-visible:bg-white" data-testid="answer-textarea" />}<div className="mt-3 flex items-center justify-between text-xs text-slate-400"><span data-testid="answer-word-count">{answer.trim() ? answer.trim().split(/\s+/).length : 0} words</span><span data-testid="answer-source-note">{source === "audio" ? "Transcribed from your recording" : isSpeaking ? "Microphone recording required" : "Text response"}</span></div><Button className="mt-6 w-full" disabled={!answer.trim() || isSubmitting || (isSpeaking && source !== "audio")} onClick={onSubmit} data-testid="submit-answer-button">{isSubmitting ? "AI is reviewing..." : "Submit for AI review"} {isSubmitting ? <LoaderCircle size={15} className="animate-spin" /> : <Send size={15} />}</Button><div className="mt-4 flex items-center justify-center gap-2 text-[11px] text-slate-400" data-testid="practice-score-note"><Sparkles size={12} className="text-teal-500" /> Feedback is an estimated practice review, not an official score</div></CardContent></Card></div></div>;
}

function LevelPicker({ level, setLevel, testId }: { level: Difficulty; setLevel: (level: Difficulty) => void; testId: string }) {
  return <label className="flex items-center gap-2 rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs font-bold text-slate-600" data-testid={`${testId}-label`}>Level<select value={level} onChange={(event) => setLevel(event.target.value as Difficulty)} className="bg-transparent font-bold text-slate-950 outline-none" data-testid={testId}>{levels.map((item) => <option value={item} key={item}>{item}</option>)}</select></label>;
}

function MockRunnerLegacy({ mock, answers, setAnswers, onSubmit, isSubmitting, onExit }: { mock: MockTest; answers: Record<string, string>; setAnswers: (answers: Record<string, string>) => void; onSubmit: () => void; isSubmitting: boolean; onExit: () => void }) {
  const [index, setIndex] = useState(0);
  const [secondsLeft, setSecondsLeft] = useState(mock.total_time_seconds);
  const question = mock.questions[index];
  const answer = answers[question.id] ?? "";
  const multiple = question.title.includes("Multiple Answers");
  useEffect(() => { const timer = window.setInterval(() => setSecondsLeft((seconds) => Math.max(0, seconds - 1)), 1000); return () => window.clearInterval(timer); }, []);
  const choose = (option: string) => { if (!multiple) { setAnswers({ ...answers, [question.id]: option }); return; } const selected = answer ? answer.split("||") : []; const next = selected.includes(option) ? selected.filter((item) => item !== option) : [...selected, option]; setAnswers({ ...answers, [question.id]: next.join("||") }); };
  const displayAnswer = multiple ? answer.split("||").filter(Boolean).join(", ") : answer;
  return <div className="mx-auto max-w-5xl animate-rise space-y-6"><div className="flex flex-wrap items-center justify-between gap-4"><div><div className="label-mono text-teal-700">Full mock test · {mock.level}</div><h1 className="mt-2 text-3xl font-extrabold tracking-tight text-slate-950" data-testid="mock-runner-title">{mock.title}</h1><p className="mt-2 text-sm text-slate-500" data-testid="mock-progress-label">Question {index + 1} of {mock.questions.length} · one attempt per question</p></div><div className={`flex items-center gap-2 rounded-lg border px-3 py-2 font-mono text-sm font-bold ${secondsLeft < 60 ? "border-rose-200 bg-rose-50 text-rose-700" : "border-slate-200 bg-white text-slate-700"}`} data-testid="mock-countdown"><TimerReset size={15} /> {Math.floor(secondsLeft / 60)}:{String(secondsLeft % 60).padStart(2, "0")}</div></div><div className="h-2 overflow-hidden rounded-full bg-slate-200" data-testid="mock-progress-bar"><div className="h-full rounded-full bg-teal-600 transition-[width] duration-300" style={{ width: `${((index + 1) / mock.questions.length) * 100}%` }} /></div><Card className="border-slate-200 shadow-sm" data-testid="mock-question-card"><CardHeader className="border-b border-slate-100"><div className="flex items-center justify-between"><Badge variant="outline" data-testid="mock-question-skill">{question.skill} · {question.task_type}</Badge><span className="text-xs font-semibold text-slate-400" data-testid="mock-question-difficulty">{question.difficulty}</span></div><CardTitle className="mt-4 text-xl" data-testid="mock-question-title">{question.title}</CardTitle></CardHeader><CardContent className="p-6"><div className="rounded-xl bg-slate-50 p-5 text-base font-medium leading-8 text-slate-800" data-testid="mock-question-prompt">{question.prompt}</div><div className="mt-5 flex gap-3 rounded-lg border border-sky-100 bg-sky-50/60 p-4 text-sm leading-relaxed text-slate-600" data-testid="mock-question-instructions"><Info size={16} className="mt-0.5 shrink-0 text-sky-600" /> {question.instructions}</div>{question.response_type === "choice" ? <div className="mt-5 space-y-2" data-testid="mock-options">{question.options.map((option) => <button type="button" key={option} onClick={() => choose(option)} className={`flex w-full items-center justify-between rounded-lg border px-4 py-3 text-left text-sm font-semibold transition-[background-color,border-color] ${answer.split("||").includes(option) ? "border-sky-500 bg-sky-50 text-sky-800" : "border-slate-200 bg-white text-slate-600 hover:border-slate-300"}`} data-testid={`mock-option-${question.order}-${option.toLowerCase().replaceAll(" ", "-")}`}>{option}{answer.split("||").includes(option) && <Check size={15} />}</button>)}</div> : <Textarea value={answer} onChange={(event) => setAnswers({ ...answers, [question.id]: event.target.value })} className="mt-5 min-h-40 border-slate-200 bg-white" placeholder="Type your response..." data-testid="mock-answer-textarea" />}<div className="mt-5 flex flex-wrap items-center justify-between gap-3"><span className="text-xs text-slate-400" data-testid="mock-answer-status">{displayAnswer ? "Answer saved for this question" : "No answer yet"}</span><div className="flex gap-2"><Button variant="outline" onClick={onExit} data-testid="mock-exit-button">Exit mock</Button>{index > 0 && <Button variant="outline" onClick={() => setIndex(index - 1)} data-testid="mock-previous-button">Previous</Button>}{index < mock.questions.length - 1 ? <Button onClick={() => setIndex(index + 1)} data-testid="mock-next-button">Next question <ArrowRight size={15} /></Button> : <Button onClick={onSubmit} disabled={isSubmitting} data-testid="mock-submit-button">{isSubmitting ? "Scoring..." : "Finish mock"} <Check size={15} /></Button>}</div></div></CardContent></Card></div>;
}

function MockRunner({ mock, answers, setAnswers, onSubmit, isSubmitting, onExit }: { mock: MockTest; answers: Record<string, string>; setAnswers: (answers: Record<string, string>) => void; onSubmit: () => void; isSubmitting: boolean; onExit: () => void }) {
  const [index, setIndex] = useState(0);
  const [secondsLeft, setSecondsLeft] = useState(mock.total_time_seconds);
  const [started, setStarted] = useState(false);
  const [paused, setPaused] = useState(false);
  const question = mock.questions[index];
  const answer = answers[question.id] ?? "";
  useEffect(() => { if (!started || paused) return; const timer = window.setInterval(() => setSecondsLeft((value) => Math.max(0, value - 1)), 1000); return () => window.clearInterval(timer); }, [started, paused]);
  if (!started) return <div className="mx-auto max-w-4xl space-y-6 animate-rise" data-testid="mock-ready-screen"><div><div className="label-mono text-teal-700">Saved full mock</div><h1 className="mt-2 text-3xl font-extrabold text-slate-950" data-testid="mock-ready-title">{mock.title}</h1><p className="mt-2 text-sm text-slate-500">{mock.questions.length} questions · {Math.ceil(mock.total_time_seconds / 60)} minutes. The timer will not start until you choose Start.</p></div><Card><CardContent className="flex flex-wrap gap-3 p-6"><Button onClick={() => setStarted(true)} data-testid="mock-start-button"><Play size={15} /> Start mock</Button><Button variant="outline" onClick={onExit} data-testid="mock-ready-exit-button">Back to mock library</Button></CardContent></Card></div>;
  const select = (value: string) => setAnswers({ ...answers, [question.id]: value });
  return <div className="mx-auto max-w-5xl space-y-6 animate-rise" data-testid="mock-runner"><div className="flex flex-wrap items-center justify-between gap-4"><div><div className="label-mono text-teal-700">Full mock · {mock.level}</div><h1 className="mt-2 text-3xl font-extrabold text-slate-950" data-testid="mock-runner-title">{mock.title}</h1><p className="mt-2 text-sm text-slate-500" data-testid="mock-progress-label">Question {index + 1} of {mock.questions.length}</p></div><div className="flex items-center gap-2"><div className="rounded-lg border border-slate-200 bg-white px-3 py-2 font-mono text-sm font-bold" data-testid="mock-countdown"><TimerReset size={15} className="inline" /> {Math.floor(secondsLeft / 60)}:{String(secondsLeft % 60).padStart(2, "0")}</div><Button variant="outline" onClick={() => setPaused((value) => !value)} data-testid={paused ? "mock-resume-button" : "mock-pause-button"}>{paused ? "Resume" : "Pause"}</Button></div></div><Card data-testid="mock-question-card"><CardHeader><Badge variant="outline" data-testid="mock-question-skill">{question.skill} · {question.task_type}</Badge><CardTitle className="mt-3" data-testid="mock-question-title">{question.title}</CardTitle></CardHeader><CardContent className="space-y-5"><div className="rounded-xl bg-slate-50 p-5" data-testid="mock-question-prompt">{question.prompt}</div>{question.response_type === "choice" ? <div className="space-y-2" data-testid="mock-options">{question.options.map((option) => <button type="button" key={option} onClick={() => select(option)} className={`w-full rounded-lg border p-3 text-left text-sm font-semibold ${answer === option ? "border-teal-500 bg-teal-50" : "border-slate-200 bg-white"}`} data-testid={`mock-option-${question.order}-${option.toLowerCase().replaceAll(/[^a-z0-9]+/g, "-")}`}>{option}</button>)}</div> : <Textarea value={answer} onChange={(event) => select(event.target.value)} className="min-h-40" data-testid="mock-answer-textarea" />}{paused && <div className="rounded-lg bg-amber-50 p-3 text-xs font-semibold text-amber-900" data-testid="mock-paused-notice">Timer paused. Resume when you are ready to continue.</div>}<div className="flex flex-wrap justify-between gap-3"><Button variant="outline" onClick={onExit} data-testid="mock-exit-button">Exit mock</Button><div className="flex gap-2">{index > 0 && <Button variant="outline" onClick={() => setIndex((value) => value - 1)} data-testid="mock-previous-button">Previous</Button>}{index < mock.questions.length - 1 ? <Button disabled={paused} onClick={() => setIndex((value) => value + 1)} data-testid="mock-next-button">Next <ArrowRight size={15} /></Button> : <Button disabled={paused || isSubmitting} onClick={onSubmit} data-testid="mock-submit-button">Finish mock <Check size={15} /></Button>}</div></div></CardContent></Card></div>;
}

function MockResultView({ result, onStartAnother, onBack }: { result: MockResult; onStartAnother: () => void; onBack: () => void }) {
  return <div className="mx-auto max-w-5xl animate-rise space-y-6"><div><div className="label-mono text-teal-700">Mock test complete</div><h1 className="mt-2 text-3xl font-extrabold tracking-tight text-slate-950" data-testid="mock-result-title">Your full mock result</h1><p className="mt-2 text-sm text-slate-500">Review the combined estimate, then use your adaptive plan for the next session.</p></div><div className="grid gap-6 lg:grid-cols-[0.8fr_1.2fr]"><Card className="border-0 bg-slate-950 text-white shadow-xl" data-testid="mock-result-score-card"><CardContent className="p-7"><div className="label-mono text-sky-300">Estimated overall</div><div className="mt-6 font-mono text-7xl font-bold tracking-[-0.1em]" data-testid="mock-result-score">{result.overall_score}</div><div className="mt-3 text-sm text-slate-300">{result.completed_count}/{result.total_count} questions answered</div></CardContent></Card><Card className="border-slate-200 shadow-sm" data-testid="mock-section-results"><CardHeader><CardTitle>Section performance</CardTitle></CardHeader><CardContent className="space-y-4">{Object.entries(result.section_scores).map(([section, score]) => <div key={section} data-testid={`mock-section-score-${section.toLowerCase().replaceAll(" ", "-")}`}><div className="flex justify-between text-sm font-semibold"><span>{section}</span><span className="font-mono">{score}</span></div><div className="mt-2 h-2 rounded-full bg-slate-100"><div className="h-full rounded-full bg-teal-600" style={{ width: `${(score / 90) * 100}%` }} /></div></div>)}</CardContent></Card></div><div className="flex flex-wrap gap-3"><Button onClick={onStartAnother} data-testid="mock-another-button"><Sparkles size={15} /> Generate another mock</Button><Button variant="outline" onClick={onBack} data-testid="mock-result-back-button">Back to dashboard</Button></div></div>;
}

function PlanView({ plan }: { plan?: StudyPlan }) {
  return <div className="mx-auto max-w-6xl animate-rise space-y-7"><div><div className="label-mono text-teal-700">Adaptive study plan</div><h1 className="mt-2 text-3xl font-extrabold tracking-tight text-slate-950" data-testid="plan-title">{plan?.title ?? "Your adaptive 7-day plan"}</h1><p className="mt-2 max-w-2xl text-sm leading-relaxed text-slate-500" data-testid="plan-summary">{plan?.summary ?? "Your plan updates as you complete more reviews."}</p></div><div className="grid gap-4 md:grid-cols-2">{(plan?.items ?? []).map((item, index) => <Card className="border-slate-200 shadow-sm" key={item.skill} data-testid={`plan-item-${item.skill.toLowerCase()}`}><CardHeader><div className="flex items-center justify-between"><div className="flex size-9 items-center justify-center rounded-lg bg-slate-50" style={{ color: skillMeta[item.skill].color }}>{index === 0 ? <Target size={17} /> : <BarChart3 size={17} />}</div><Badge variant={item.priority === "High" ? "default" : "outline"} data-testid={`plan-priority-${item.skill.toLowerCase()}`}>{item.priority} priority</Badge></div><CardTitle className="mt-3 text-lg">{item.title}</CardTitle></CardHeader><CardContent><p className="text-sm leading-relaxed text-slate-500" data-testid={`plan-detail-${item.skill.toLowerCase()}`}>{item.detail}</p><div className="mt-4 flex items-center gap-2 text-xs font-bold text-slate-600"><span className="flex size-5 items-center justify-center rounded-full bg-teal-100 text-teal-700"><Check size={12} /></span>{item.task_count} focused tasks this week</div></CardContent></Card>)}</div><div className="flex items-center gap-3 rounded-xl border border-sky-100 bg-sky-50/70 p-4 text-xs leading-relaxed text-sky-900" data-testid="plan-disclaimer"><Info size={15} className="shrink-0 text-sky-600" /> This plan is generated from your completed practice and updates as your weakest skill changes.</div></div>;
}

function CatalogView({ plans }: { plans: PricingPlan[] }) {
  return <div className="mx-auto max-w-6xl animate-rise space-y-7"><div><div className="label-mono text-teal-700">Access catalog</div><h1 className="mt-2 text-3xl font-extrabold tracking-tight text-slate-950" data-testid="catalog-title">Choose the way you want to train</h1><p className="mt-2 max-w-2xl text-sm leading-relaxed text-slate-500" data-testid="catalog-subtitle">Module, section, and full mock options are mapped out for your launch. Payment is not active yet.</p></div><div className="grid gap-5 md:grid-cols-2 xl:grid-cols-4">{plans.map((plan) => <Card className="border-slate-200 shadow-sm" key={plan.id} data-testid={`pricing-card-${plan.id}`}><CardHeader><Badge variant="outline" data-testid={`pricing-scope-${plan.id}`}>{plan.scope}</Badge><CardTitle className="mt-4 text-xl" data-testid={`pricing-name-${plan.id}`}>{plan.name}</CardTitle><div className="font-mono text-3xl font-bold text-slate-950" data-testid={`pricing-price-${plan.id}`}>{plan.price}</div></CardHeader><CardContent><p className="min-h-12 text-sm leading-relaxed text-slate-500">{plan.description}</p><div className="mt-5 space-y-2">{plan.features.map((feature) => <div className="flex gap-2 text-xs font-semibold text-slate-600" key={feature}><Check size={14} className="shrink-0 text-teal-600" />{feature}</div>)}</div><Button variant="outline" className="mt-6 w-full" disabled data-testid={`pricing-unavailable-${plan.id}`}>Payment coming later</Button></CardContent></Card>)}</div><div className="flex items-center gap-3 rounded-xl border border-amber-100 bg-amber-50/70 p-4 text-xs leading-relaxed text-amber-900" data-testid="catalog-payment-note"><Info size={15} className="shrink-0 text-amber-600" /> No payment mode is connected. This catalog is ready for a future checkout without pretending a purchase happened.</div></div>;
}

function HistoryView({ attempts, onPractice }: { attempts: Attempt[]; onPractice: () => void }) {
  return <div className="mx-auto max-w-6xl animate-rise space-y-7"><div><div className="label-mono text-teal-700">Your practice log</div><h1 className="mt-2 text-3xl font-extrabold tracking-tight text-slate-950" data-testid="history-title">Progress history</h1><p className="mt-2 text-sm text-slate-500">Review completed work and keep your next step visible.</p></div><Card className="border-slate-200 shadow-sm" data-testid="history-card"><CardHeader className="border-b border-slate-100"><div className="flex items-center justify-between"><CardTitle className="text-lg">Completed practice</CardTitle><Badge variant="outline" data-testid="history-count-badge">{attempts.length} reviews</Badge></div></CardHeader><CardContent className="p-0">{attempts.length ? <div className="divide-y divide-slate-100">{attempts.map((attempt) => <div className="flex flex-wrap items-center justify-between gap-4 px-6 py-5" key={attempt.id} data-testid={`history-row-${attempt.id}`}><div className="flex items-center gap-3"><span className="flex size-9 items-center justify-center rounded-lg bg-slate-50 text-sky-600"><Check size={16} /></span><div><div className="text-sm font-bold text-slate-900">{attempt.task_title}</div><div className="mt-1 text-xs text-slate-500">{attempt.skill} · {attempt.difficulty} · {attempt.source === "audio" ? "audio" : `${attempt.word_count} words`} · {new Date(attempt.created_at).toLocaleDateString()}</div></div></div><div className="flex items-center gap-5"><div className="text-right"><div className="font-mono text-xl font-bold text-slate-900">{attempt.score}</div><div className="text-[10px] font-bold uppercase tracking-wider text-slate-400">estimate</div></div><ChevronRight size={16} className="text-slate-300" /></div></div>)}</div> : <div className="p-10 text-center"><History className="mx-auto text-slate-300" size={30} /><p className="mt-3 text-sm font-semibold text-slate-700" data-testid="history-empty-title">Your first review is waiting</p><Button className="mt-5" onClick={onPractice} data-testid="history-start-practice-button">Start practice <ArrowRight size={15} /></Button></div>}</CardContent></Card></div>;
}

export default function Home() {
  const queryClient = useQueryClient();
  const [view, setView] = useState<View>("overview");
  const [level, setLevel] = useState<Difficulty>("Medium");
  const [moduleSkill, setModuleSkill] = useState<Skill>("Speaking");
  const [selectedTask, setSelectedTask] = useState<PteTask | null>(null);
  const [answer, setAnswer] = useState("");
  const [source, setSource] = useState<"text" | "audio">("text");
  const [audioDuration, setAudioDuration] = useState<number>();
  const [submittedAttempt, setSubmittedAttempt] = useState<Attempt | null>(null);
  const [mock, setMock] = useState<MockTest | null>(null);
  const [mockAnswers, setMockAnswers] = useState<Record<string, string>>({});
  const [mockResult, setMockResult] = useState<MockResult | null>(null);
  const dashboardQuery = useQuery({ queryKey: ["pte-dashboard"], queryFn: fetchDashboard, retry: false });
  const tasksQuery = useQuery({ queryKey: ["pte-tasks", level], queryFn: () => apiGet<PteTask[]>(`/pte/tasks?level=${level}`), retry: false });
  const attemptsQuery = useQuery({ queryKey: ["pte-attempts"], queryFn: fetchAttempts, retry: false });
  const planQuery = useQuery({ queryKey: ["pte-plan"], queryFn: fetchPlan, retry: false, enabled: view === "plan" || view === "overview" });
  const pricingQuery = useQuery({ queryKey: ["pte-pricing"], queryFn: fetchPricing, retry: false, enabled: view === "catalog" });
  const submitMutation = useMutation({ mutationFn: (payload: AttemptCreate) => apiPost<Attempt>("/pte/attempts", payload), onSuccess: (attempt) => { setSubmittedAttempt(attempt); setAnswer(""); queryClient.invalidateQueries({ queryKey: ["pte-dashboard"] }); queryClient.invalidateQueries({ queryKey: ["pte-attempts"] }); toast.success("Practice reviewed", { description: attempt.ai_feedback ? "AI feedback is ready." : "Your fallback review is ready." }); }, onError: () => toast.error("Could not submit", { description: "Please try again in a moment." }) });
  const mockMutation = useMutation({ mutationFn: (mockLevel: Difficulty) => apiPost<MockTest>("/pte/mocks", { level: mockLevel }), onSuccess: (result) => { setMock(result); setMockAnswers({}); setMockResult(null); setView("mock"); toast.success(result.generated_by_ai ? "New AI mock generated" : "New curated mock ready", { description: `${result.questions.length} task types at ${result.level} difficulty.` }); }, onError: () => toast.error("Mock generation failed", { description: "The curated question bank is still available." }) });
  const mockSubmitMutation = useMutation({ mutationFn: ({ mockId, answers }: { mockId: string; answers: MockAnswer[] }) => apiPost<MockResult>(`/pte/mocks/${mockId}/submit`, { answers }), onSuccess: (result) => { setMockResult(result); queryClient.invalidateQueries({ queryKey: ["pte-dashboard"] }); toast.success("Mock scored", { description: "Your combined result is ready." }); } });
  const dashboard = dashboardQuery.data;
  const tasks = tasksQuery.data ?? [];
  const openPractice = (task?: PteTask) => { setSubmittedAttempt(null); setSelectedTask(task ?? null); setAnswer(""); setSource("text"); setView("practice"); window.scrollTo({ top: 0, behavior: "smooth" }); };
  const openModule = (skill: Skill) => { setModuleSkill(skill); setSelectedTask(null); setSubmittedAttempt(null); setView("module"); window.scrollTo({ top: 0, behavior: "smooth" }); };
  const navigate = (next: View) => { setView(next); if (next !== "practice") { setSelectedTask(null); setSubmittedAttempt(null); } window.scrollTo({ top: 0, behavior: "smooth" }); };
  const submitAttempt = () => { if (!selectedTask || !answer.trim()) return; submitMutation.mutate({ task_id: selectedTask.id, answer_text: answer, difficulty: level, source, audio_duration_seconds: audioDuration }); };
  const startMock = (value?: unknown) => {
    setMockResult(null);
    if (value && typeof value === "object" && "id" in value && !("nativeEvent" in value)) { setMock(value as MockTest); setView("mock"); return; }
    if (value) { mockMutation.mutate(level); return; }
    setView("mock");
  };
  const navItems: { label: string; view: View; icon: typeof LayoutDashboard }[] = [{ label: "Dashboard", view: "overview", icon: LayoutDashboard }, { label: "Practice", view: "practice", icon: Target }, { label: "Full mock", view: "mock", icon: TimerReset }, { label: "Study plan", view: "plan", icon: BarChart3 }, { label: "History", view: "history", icon: History }];
  return <div className="min-h-svh bg-[#f8fafc] text-slate-900"><header className="sticky top-0 z-20 border-b border-slate-200/80 bg-white/90 backdrop-blur-xl" data-testid="app-header"><div className="mx-auto flex min-h-[72px] max-w-[1440px] items-center justify-between gap-4 px-4 sm:px-6 lg:px-8"><button type="button" className="flex items-center gap-3 text-left" onClick={() => navigate("overview")} data-testid="brand-home-button"><span className="flex size-10 items-center justify-center rounded-xl bg-slate-950 text-white shadow-lg shadow-slate-900/15"><BrainCircuit size={21} /></span><span><span className="block font-heading text-base font-extrabold tracking-tight text-slate-950" data-testid="brand-name">PTE Prep</span><span className="block text-[10px] font-bold uppercase tracking-[0.2em] text-teal-600">Train with intent</span></span></button><nav className="hidden items-center gap-1 rounded-xl bg-slate-50 p-1 xl:flex" aria-label="Primary navigation" data-testid="primary-navigation">{navItems.map((item) => { const Icon = item.icon; return <button type="button" className={`nav-button ${view === item.view ? "nav-button-active" : ""}`} onClick={() => item.view === "mock" ? (mock ? navigate("mock") : startMock()) : navigate(item.view)} key={item.view} data-testid={`nav-${item.view}-button`}><Icon size={15} /> {item.label}</button>; })}<button type="button" className="nav-button" onClick={() => navigate("catalog")} data-testid="nav-catalog-button"><Trophy size={15} /> Catalog</button></nav><div className="flex items-center gap-3"><div className="hidden items-center gap-2 rounded-full border border-amber-100 bg-amber-50 px-3 py-1.5 text-xs font-semibold text-amber-700 sm:flex" data-testid="streak-badge"><Flame size={14} /> {dashboard?.streak_days ?? 12} day streak</div><div className="flex size-9 items-center justify-center rounded-full bg-teal-100 text-xs font-bold text-teal-800" data-testid="profile-avatar">AR</div></div></div></header><div className="mx-auto flex max-w-[1440px]"><aside className="hidden w-60 shrink-0 border-r border-slate-200/80 px-5 py-8 lg:block" data-testid="desktop-sidebar"><div className="label-mono px-3 text-slate-400">Your workspace</div><div className="mt-4 space-y-1">{navItems.map((item) => { const Icon = item.icon; return <button type="button" className={`side-link ${view === item.view ? "side-link-active" : ""}`} onClick={() => item.view === "mock" ? (mock ? navigate("mock") : startMock()) : navigate(item.view)} key={item.view} data-testid={`sidebar-${item.view}-button`}><Icon size={16} /> {item.label}</button>; })}<button type="button" className={`side-link ${view === "catalog" ? "side-link-active" : ""}`} onClick={() => navigate("catalog")} data-testid="sidebar-catalog-button"><Trophy size={16} /> Access catalog</button></div><div className="mt-12 rounded-xl bg-slate-950 p-4 text-white"><div className="flex size-8 items-center justify-center rounded-lg bg-teal-400/20 text-teal-300"><Trophy size={16} /></div><div className="mt-4 text-sm font-bold" data-testid="sidebar-goal-title">Your goal</div><div className="mt-1 text-xs leading-relaxed text-slate-400">Build habits that move you toward 79+.</div><div className="mt-4 h-1.5 rounded-full bg-white/10"><div className="h-full w-[72%] rounded-full bg-teal-400" /></div></div></aside><main className="min-w-0 flex-1 px-4 py-7 sm:px-6 lg:px-10 lg:py-10">{view === "overview" && <Overview dashboard={dashboard} tasks={tasks} level={level} setLevel={setLevel} onPractice={openPractice} onModule={openModule} onNavigate={navigate} />}{view === "practice" && !submittedAttempt && <PracticeCenter tasks={tasks} level={level} setLevel={setLevel} selectedTask={selectedTask} setSelectedTask={setSelectedTask} answer={answer} setAnswer={setAnswer} source={source} setSource={setSource} audioDuration={audioDuration} setAudioDuration={setAudioDuration} isSubmitting={submitMutation.isPending} onSubmit={submitAttempt} onBack={() => navigate("overview")} />}{view === "practice" && submittedAttempt && <FeedbackView attempt={submittedAttempt} onBack={() => navigate("overview")} onRetry={() => { setSubmittedAttempt(null); setSelectedTask(selectedTask); }} />}{view === "module" && <ModuleTests skill={moduleSkill} level={level} setLevel={setLevel} onBack={() => navigate("overview")} />}{view === "history" && <HistoryView attempts={attemptsQuery.data ?? []} onPractice={() => openPractice()} />}{view === "plan" && <PlanView plan={planQuery.data} />}{view === "catalog" && <CatalogView plans={pricingQuery.data ?? []} />}{view === "mock" && !mockResult && (mock ? <MockRunner mock={mock} answers={mockAnswers} setAnswers={setMockAnswers} isSubmitting={mockSubmitMutation.isPending} onExit={() => navigate("overview")} onSubmit={() => mockSubmitMutation.mutate({ mockId: mock.id, answers: Object.entries(mockAnswers).map(([question_id, answer]) => ({ question_id, answer })) })} /> : <MockLanding level={level} setLevel={setLevel} loading={mockMutation.isPending} onStart={startMock} />)}{view === "mock" && mockResult && <MockResultView result={mockResult} onStartAnother={startMock} onBack={() => navigate("overview")} />}</main></div><div className="fixed bottom-5 left-5 z-10 flex items-center gap-2 rounded-full border border-slate-200 bg-white/95 px-3 py-2 text-[11px] font-semibold text-slate-500 shadow-lg shadow-slate-900/5" data-testid="ai-mode-indicator"><span className="size-1.5 rounded-full bg-teal-500" /> Managed AI + Whisper active</div></div>;
}

function Overview({ dashboard, tasks, level, setLevel, onPractice, onModule, onNavigate }: { dashboard?: DashboardSummary; tasks: PteTask[]; level: Difficulty; setLevel: (level: Difficulty) => void; onPractice: (task?: PteTask) => void; onModule: (skill: Skill) => void; onNavigate: (view: View) => void }) {
  const firstTask = tasks[0];
  const grouped = tasks.reduce<Record<Skill, PteTask[]>>((result, task) => { result[task.skill].push(task); return result; }, { Speaking: [], Writing: [], Reading: [], Listening: [] });
  return <div className="mx-auto max-w-7xl animate-rise space-y-8"><section className="relative overflow-hidden rounded-2xl bg-slate-950 p-6 text-white shadow-xl shadow-slate-900/10 sm:p-8" data-testid="dashboard-hero"><div className="absolute -right-20 -top-32 size-80 rounded-full bg-sky-400/10 blur-3xl" /><div className="relative grid items-center gap-8 lg:grid-cols-[1fr_auto]"><div><div className="label-mono text-teal-300">Tuesday · your focus session</div><h1 className="mt-4 max-w-xl text-3xl font-extrabold tracking-[-0.04em] sm:text-4xl" data-testid="dashboard-heading">Make every practice minute count.</h1><p className="mt-4 max-w-lg text-sm leading-relaxed text-slate-300">Original tasks, meaningful feedback, and a plan that adapts as you improve.</p><div className="mt-7 flex flex-wrap gap-3"><Button className="bg-teal-400 text-slate-950 hover:bg-teal-300" onClick={() => onPractice(firstTask)} data-testid="hero-start-practice-button"><Play size={15} fill="currentColor" /> Start practice</Button><Button variant="outline" className="border-white/20 bg-white/5 text-white hover:bg-white/10 hover:text-white" onClick={() => onNavigate("mock")} data-testid="hero-start-mock-button"><TimerReset size={15} /> Full mock</Button></div></div><div className="flex justify-center lg:pr-8"><ScoreRing score={dashboard?.overall_score ?? 69} target={dashboard?.target_score ?? 79} /></div></div></section><div className="flex flex-wrap items-end justify-between gap-4"><div><div className="label-mono text-slate-400">Current skill scores</div><h2 className="mt-2 text-2xl font-extrabold tracking-tight text-slate-950" data-testid="skill-score-title">Open a skill to start a 20-question test</h2></div><LevelPicker level={level} setLevel={setLevel} testId="dashboard-level-picker" /></div><section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4" data-testid="skill-score-grid">{skills.map((skill) => <SkillCard key={skill} skill={skill} score={dashboard?.skill_scores[skill] ?? 0} task={grouped[skill][0]} onPractice={() => onModule(skill)} />)}</section><section className="grid gap-6 xl:grid-cols-[1.35fr_0.65fr]"><div><div className="mb-4 flex items-end justify-between"><div><div className="label-mono text-slate-400">Practice library</div><h2 className="mt-2 text-2xl font-extrabold tracking-tight text-slate-950" data-testid="task-section-title">Choose a focused warm-up</h2></div><button type="button" className="flex items-center gap-1 text-xs font-bold text-sky-700 transition-colors hover:text-sky-900" onClick={() => onNavigate("practice")} data-testid="view-all-tasks-button">View all 20 <ArrowRight size={14} /></button></div><div className="grid gap-4 sm:grid-cols-2">{tasks.slice(0, 4).map((task) => <TaskCard key={task.id} task={task} onSelect={() => onPractice(task)} />)}</div></div><Card className="self-start border-slate-200 shadow-sm" data-testid="weak-area-card"><CardHeader><div className="flex items-center justify-between"><div className="flex size-9 items-center justify-center rounded-lg bg-amber-50 text-amber-600"><Target size={17} /></div><Badge variant="outline">Needs attention</Badge></div><CardTitle className="mt-4 text-lg">Strengthen your {dashboard?.weak_area ?? "Listening"}</CardTitle></CardHeader><CardContent><p className="text-sm leading-relaxed text-slate-500">Complete a full skill test so your correct answers and mistakes are stored together.</p><Button variant="outline" className="mt-5 w-full" onClick={() => onModule(dashboard?.weak_area ?? "Listening")} data-testid="weak-area-practice-button">Start weak-skill test <ArrowRight size={15} /></Button></CardContent></Card></section><section><div className="mb-4 flex items-end justify-between"><div><div className="label-mono text-slate-400">Next layer</div><h2 className="mt-2 text-2xl font-extrabold tracking-tight text-slate-950" data-testid="next-layer-title">Practice with a system</h2></div><div className="hidden items-center gap-2 text-xs text-slate-500 sm:flex" data-testid="catalog-count"><span className="size-1.5 rounded-full bg-teal-500" /> {tasks.length} original task types</div></div><div className="grid gap-4 md:grid-cols-3"><button type="button" className="rounded-xl border border-slate-200 bg-white p-5 text-left shadow-sm transition-[transform,box-shadow] hover:-translate-y-0.5 hover:shadow-md" onClick={() => onNavigate("mock")} data-testid="dashboard-mock-card"><div className="flex size-9 items-center justify-center rounded-lg bg-sky-50 text-sky-600"><TimerReset size={17} /></div><div className="mt-5 text-sm font-bold text-slate-900">Full 20-type mock</div><div className="mt-1 text-xs leading-relaxed text-slate-500">Generate a new level-based simulation whenever you start.</div></button><button type="button" className="rounded-xl border border-slate-200 bg-white p-5 text-left shadow-sm transition-[transform,box-shadow] hover:-translate-y-0.5 hover:shadow-md" onClick={() => onNavigate("plan")} data-testid="dashboard-plan-card"><div className="flex size-9 items-center justify-center rounded-lg bg-teal-50 text-teal-600"><BarChart3 size={17} /></div><div className="mt-5 text-sm font-bold text-slate-900">Adaptive study plan</div><div className="mt-1 text-xs leading-relaxed text-slate-500">Let your weakest skill decide what gets attention next.</div></button><button type="button" className="rounded-xl border border-slate-200 bg-white p-5 text-left shadow-sm transition-[transform,box-shadow] hover:-translate-y-0.5 hover:shadow-md" onClick={() => onNavigate("catalog")} data-testid="dashboard-catalog-card"><div className="flex size-9 items-center justify-center rounded-lg bg-amber-50 text-amber-600"><Trophy size={17} /></div><div className="mt-5 text-sm font-bold text-slate-900">Access catalog</div><div className="mt-1 text-xs leading-relaxed text-slate-500">Review single-skill, section, and full mock options.</div></button></div></section></div>;
}

function MockLandingLegacy({ level, setLevel, loading, onStart }: { level: Difficulty; setLevel: (level: Difficulty) => void; loading: boolean; onStart: () => void }) {
  return <div className="mx-auto max-w-5xl animate-rise space-y-7"><div><div className="label-mono text-teal-700">Full mock simulator</div><h1 className="mt-2 text-3xl font-extrabold tracking-tight text-slate-950" data-testid="mock-landing-title">Build a fresh 20-type mock</h1><p className="mt-2 max-w-2xl text-sm leading-relaxed text-slate-500">Every mock combines Speaking, Writing, Reading, and Listening tasks with a single timer, question order, and combined result.</p></div><Card className="border-slate-200 shadow-sm" data-testid="mock-setup-card"><CardContent className="grid items-center gap-8 p-7 lg:grid-cols-[1fr_auto]"><div><div className="flex items-center gap-3"><span className="flex size-11 items-center justify-center rounded-xl bg-sky-50 text-sky-600"><TimerReset size={22} /></span><div><div className="text-lg font-bold text-slate-900">PTE Academic simulation</div><div className="mt-1 text-xs text-slate-500">20 task types · generated prompts · timed transitions</div></div></div><div className="mt-7 grid gap-3 sm:grid-cols-3">{["20 questions", "4 skills", "One result"].map((item) => <div className="rounded-lg bg-slate-50 p-3 text-center text-xs font-bold text-slate-600" key={item} data-testid={`mock-feature-${item.toLowerCase().replaceAll(" ", "-")}`}>{item}</div>)}</div></div><div className="flex flex-col items-stretch gap-3 rounded-xl bg-slate-950 p-5 text-white"><LevelPicker level={level} setLevel={setLevel} testId="mock-level-picker" /><Button className="bg-teal-400 text-slate-950 hover:bg-teal-300" disabled={loading} onClick={onStart} data-testid="generate-mock-button">{loading ? "Generating..." : "Generate new mock"} {loading ? <LoaderCircle size={15} className="animate-spin" /> : <Sparkles size={15} />}</Button></div></CardContent></Card><div className="flex items-center gap-3 rounded-xl border border-teal-100 bg-teal-50/70 p-4 text-xs leading-relaxed text-teal-900" data-testid="mock-generation-note"><Sparkles size={15} className="shrink-0 text-teal-600" /> AI creates original prompts at the selected level, with a curated fallback so you can always practice.</div></div>;
}

function MockLanding({ level, setLevel, loading, onStart }: { level: Difficulty; setLevel: (level: Difficulty) => void; loading: boolean; onStart: (value?: MockTest | unknown) => void }) {
  const savedMocks = useQuery({ queryKey: ["pte-saved-mocks", level], queryFn: () => apiGet<MockTest[]>(`/pte/mocks?level=${level}`), retry: false });
  return <div className="mx-auto max-w-5xl space-y-6 animate-rise" data-testid="mock-library"><MockLandingLegacy level={level} setLevel={setLevel} loading={loading} onStart={onStart as () => void} /><section data-testid="saved-mock-list"><div className="mb-3 text-lg font-bold text-slate-950">Your saved mocks</div><div className="grid gap-3 md:grid-cols-2">{(savedMocks.data ?? []).map((mock) => <Card key={mock.id} data-testid={`saved-mock-${mock.id}`}><CardContent className="flex items-center justify-between gap-3 p-5"><div><div className="font-bold text-slate-900">{mock.title}</div><div className="mt-1 text-xs text-slate-500">{mock.questions.length} questions · {mock.level}</div></div><Button onClick={() => onStart(mock)} data-testid={`start-saved-mock-${mock.id}`}><Play size={14} /> Start</Button></CardContent></Card>)}{!(savedMocks.data ?? []).length && <div className="rounded-xl border border-dashed border-slate-300 p-5 text-sm text-slate-500" data-testid="saved-mocks-empty">No saved mocks at this level yet. Generate one when you are ready.</div>}</div></section></div>;
}